"""Standalone viewer for precomputed v4 artifacts; no server or model calls."""
import json


def render_viewer(forecast, audience, decision, validation, manifest, audit, assets):
    data = json.dumps({"forecast": forecast, "audience": audience, "decision": decision,
                       "validation": validation, "manifest": manifest, "audit": audit,
                       "assets": assets}, ensure_ascii=False, allow_nan=False).replace("<", "\\u003c")
    return TEMPLATE.replace("__DATA__", data)


TEMPLATE = r'''<!doctype html>
<html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Wevion · previsioni, pubblici e decisioni</title>
<style>
:root{color-scheme:light dark;--font-sans:Inter,system-ui,sans-serif;--font-mono:monospace}
*{box-sizing:border-box}html,body{margin:0;background:transparent;color:var(--foreground,light-dark(#22232b,#eeeef5));font:14px/1.5 var(--font-sans)}
button,select{font:inherit;color:inherit;background:var(--card,light-dark(#fff,#23242c));border:1px solid var(--border,light-dark(#dedee9,#444553));border-radius:8px;padding:8px}button{cursor:pointer}select{max-width:100%}h1{font-size:24px;margin:0 0 4px}h2{font-size:17px;margin:0 0 12px}h3{font-size:15px;margin:12px 0 6px}p{margin:6px 0 12px}.muted{color:var(--muted-foreground,light-dark(#6a6b79,#b3b3c3))}.small{font-size:12px}.controls{display:flex;flex-wrap:wrap;gap:12px;margin:18px 0}.controls label{display:grid;gap:4px;font-size:12px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card{padding:16px;border:1px solid var(--border,light-dark(#dedee9,#444553));background:var(--card,light-dark(#f8f8fb,#23242c));border-radius:var(--radius,12px);margin-bottom:14px}.big{font-size:27px;font-weight:650;letter-spacing:-1px}.tabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px}.tabs button[aria-selected=true]{color:var(--primary,#8062e3);border-color:var(--primary,#8062e3)}[hidden]{display:none!important}.tablewrap{overflow:auto;max-height:470px}table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:left;padding:8px 9px;border-bottom:1px solid var(--border,light-dark(#dedee9,#444553));vertical-align:top}th{white-space:nowrap}.note{border-left:3px solid var(--primary,#8062e3);padding-left:12px}.tag{font-size:11px;color:var(--primary,#8062e3)}.chart{height:185px;width:100%;display:block}.barrow{display:grid;grid-template-columns:80px 1fr 60px;gap:8px;align-items:center;margin:9px 0;font-size:12px}.track{height:14px;background:var(--secondary,light-dark(#e8e8f0,#353641));border-radius:4px;overflow:hidden}.fill{height:100%;background:var(--chart-1,#9277ee)}.fill.alt{background:var(--chart-2,#2eaa8c)}a{color:var(--primary,#8062e3)}summary{cursor:pointer;font-weight:600}details{margin:10px 0}ul{padding-left:19px}.hero{margin-bottom:18px}button:focus-visible,select:focus-visible{outline:2px solid var(--primary,#8062e3);outline-offset:2px}@media(max-width:580px){.grid{grid-template-columns:1fr}.two{grid-template-columns:1fr}h1{font-size:21px}}
</style><body>
<div class="hero"><h1>Decidere prima di spendere</h1><p class="muted">Pubblici ipotizzati, CTR/CPM e scenari di allocazione · Meta · 16–30 novembre 2026</p><p class="small note">Prototipo sui dati simulati Wevion. Le stime e gli scenari sono condizionali; conversioni e ricavi non sono disponibili.</p></div>
<div class="grid"><div class="card"><div class="big">699</div><span class="muted">previsioni annuncio/giorno</span></div><div class="card"><div class="big">12</div><span class="muted">pubblici con evidenze e alternative</span></div><div class="card"><div class="big">15</div><span class="muted">giorni · Black Friday e Cyber Monday</span></div></div>
<div class="controls"><label>Settore<select id="vertical"></select></label><label>Giorno<select id="day"></select></label><label>Gruppo di annunci<select id="adset"></select></label></div>
<div class="tabs" role="tablist"><button role="tab" aria-selected="true" data-tab="recommendations">Decisioni</button><button role="tab" aria-selected="false" data-tab="forecasts">Previsioni</button><button role="tab" aria-selected="false" data-tab="audiences">Pubblici</button><button role="tab" aria-selected="false" data-tab="validation">Validazione e limiti</button></div>
<section id="recommendations" role="tabpanel"><div class="card" id="recommendation"></div><div class="two"><div class="card"><h2>CTR previsto nel periodo</h2><svg id="ctrChart" class="chart" role="img" aria-label="CTR previsto del gruppo giorno per giorno"></svg></div><div class="card"><h2>CPM previsto nel periodo</h2><svg id="cpmChart" class="chart" role="img" aria-label="CPM previsto del gruppo giorno per giorno"></svg></div></div><div class="card"><h2>Budget nella campagna · stesso totale</h2><p class="small muted">Riallocazione entro ±20% per gruppo. Pacing e quote di delivery stimati dallo storico rimangono fissi nello scenario.</p><div class="tablewrap" id="budgetTable"></div></div></section>
<section id="forecasts" role="tabpanel" hidden><div class="card"><h2>Previsioni per annuncio</h2><p class="small muted">Filtrate per settore, gruppo e giorno. Gli intervalli probabilistici non sono ancora calibrati; l'incertezza aumenta per nuovi annunci e Black Friday.</p><div class="tablewrap" id="forecastTable"></div><p class="small"><a href="forecasts_2026-11-16_30.csv" download>Scarica tutte le 699 previsioni CSV</a> · <a href="seasonal_scenarios.csv" download>Scenari stagionali dal benchmark 2025</a></p></div></section>
<section id="audiences" role="tabpanel" hidden><div class="card"><h2>Un'ipotesi per ciascun pubblico</h2><p class="small muted">Descrizioni comportamentali dedotte dagli indizi del kit. Età, genere e pubblico reale non sono identificabili. Confidenza qualitativa bassa.</p><div id="audienceCards"></div></div></section>
<section id="validation" role="tabpanel" hidden><div class="card"><h2>Backtest cronologici</h2><p class="small muted">Le previsioni usano soltanto dati fino al cutoff. I grafici confrontano errori ponderati per impression, non livelli di CTR/CPM.</p><div id="validationCharts"></div></div><div class="card"><h2>Che cosa resta da verificare</h2><ul id="remaining"></ul><p class="small note">Le due finestre di validazione precedono il Black Friday: non misurano direttamente l'accuratezza durante quell'evento. Le varianti stagionali sono ipotesi di pressione, non intervalli di confidenza.</p><p class="small" id="source"></p><p class="small" id="qa"></p></div></section>
<p class="small muted">La consegna include CSV, schede pubblico, decisioni, metriche e metodologia. Le simulazioni di reazioni con Decision 1 sono un'estensione opzionale.</p>
<script id="payload" type="application/json">__DATA__</script>
<script>
const D=JSON.parse(document.getElementById('payload').textContent),$=id=>document.getElementById(id),money=n=>Number(n).toLocaleString('it-IT',{style:'currency',currency:'EUR'}),num=(n,p=2)=>Number(n).toLocaleString('it-IT',{maximumFractionDigits:p}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={beauty_skincare:'Beauty e skincare',pet_ecommerce:'Pet e-commerce',abbigliamento:'Abbigliamento'};
function options(id,values,label){$(id).replaceChildren(...values.map(v=>{const o=document.createElement('option');o.value=v;o.textContent=label?label(v):v;return o}))}
options('vertical',[...new Set(D.forecast.map(r=>r.vertical))],v=>names[v]||v);options('day',[...new Set(D.forecast.map(r=>r.data))].sort());
function table(headers,rows){return '<table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function line(id,values,unit){const svg=$(id),w=480,h=185,p=35,max=Math.max(...values.map(x=>x[1]))*1.12,min=Math.max(0,Math.min(...values.map(x=>x[1]))*.85),scale=v=>h-p-(v-min)/(max-min||1)*(h-2*p),pts=values.map((v,i)=>[p+i*(w-2*p)/Math.max(1,values.length-1),scale(v[1])]);svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML=`<line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" stroke="currentColor" opacity=".2"/><polyline points="${pts.map(x=>x.join(',')).join(' ')}" fill="none" stroke="var(--chart-1,#9277ee)" stroke-width="3"/>`+pts.map((pt,i)=>`<circle cx="${pt[0]}" cy="${pt[1]}" r="3" fill="var(--chart-1,#9277ee)"><title>${values[i][0]}: ${num(values[i][1])}${unit}</title></circle>`).join('')+`<text x="${p}" y="16" fill="currentColor" font-size="11">${num(max)}${unit}</text><text x="${p}" y="${h-8}" fill="currentColor" font-size="11">16 nov</text><text x="${w-p-40}" y="${h-8}" fill="currentColor" font-size="11">30 nov</text>`}
function refreshSets(){options('adset',D.audience.adsets.filter(r=>r.vertical===$('vertical').value).map(r=>r.adset_id));render()}
function render(){const vertical=$('vertical').value,day=$('day').value,adset=$('adset').value,row=D.decision.rows.find(r=>r.data===day&&r.adset_id===adset);if(!row)return;const asset=D.assets.find(a=>a.asset_id===row.recommended_asset_id);$('recommendation').innerHTML=`<span class="tag">${esc(adset)} · ${esc(day)}</span><h2>Creatività da valutare: ${esc(asset?asset.headline:row.recommended_asset_id)}</h2><p>${esc(row.recommended_lever)} · ${esc(row.recommended_format)} · ${esc(row.recommended_ad_id)}</p><div class="two"><div><strong>${money(row.budget_scenario_eur)}</strong> di budget proposto <span class="muted">(${row.budget_delta_eur>=0?'+':''}${money(row.budget_delta_eur)})</span><p class="small">Spesa effettiva assunta: ${money(row.effective_spend_scenario_eur)} · pacing ${num(100*row.pacing)}%</p></div><div><strong>${num(row.expected_clicks_scenario)}</strong> click nello scenario <span class="muted">vs ${num(row.expected_clicks_base)} a budget iniziale</span><p class="small">eCTR gruppo ${num(row.ectr_pct)}% · eCPM ${money(row.ecpm_eur)}</p></div></div><p class="small muted">${esc(row.reason)}. Le stime del gruppo usano il mix di delivery, non il solo annuncio consigliato.</p><p class="small note">${esc(row.uncertainty)}</p>`;
const series=D.decision.rows.filter(r=>r.adset_id===adset).sort((a,b)=>a.data.localeCompare(b.data));line('ctrChart',series.map(r=>[r.data,r.ectr_pct]),'%');line('cpmChart',series.map(r=>[r.data,r.ecpm_eur]),' €');
const budget=D.decision.rows.filter(r=>r.data===day&&r.campaign_id===row.campaign_id);$('budgetTable').innerHTML=table(['Gruppo','Budget iniziale','Scenario','Differenza','Click stimati'],budget.map(r=>[esc(r.adset_id),money(r.budget_base_eur),money(r.budget_scenario_eur),money(r.budget_delta_eur),num(r.expected_clicks_scenario)]));
const forecast=D.forecast.filter(r=>r.vertical===vertical&&r.data===day&&r.adset_id===adset);$('forecastTable').innerHTML=table(['Annuncio','Asset','Leva','CTR','CPM','Storia'],forecast.map(r=>[esc(r.ad_id),esc(r.asset_id),esc(r.leva),num(r.ctr_predetto_pct,3)+'%',money(r.cpm_predetto_eur),r.cold_start?'Nuovo':'Disponibile']));
$('audienceCards').innerHTML=D.audience.adsets.filter(r=>r.vertical===vertical).map(r=>`<details ${r.adset_id===adset?'open':''}><summary>${esc(r.adset_id)} · ${esc(r.segmento_ipotizzato)}</summary><p class="small">CTR storico ${num(r.segnali_osservati.ctr_storico_pct,3)}% · CPM ${money(r.segnali_osservati.cpm_storico_eur)} · dati fino al ${esc(r.cutoff)}</p><p>${esc(r.strategie)}</p><p class="small muted">Alternativa: ${esc(r.alternative[0])}</p><p class="small note">${esc(r.caution)}</p></details>`).join('')}
const reported=D.validation.reported_external,folds=reported?reported.backtest:[];let charts='';for(const fold of folds){charts+=`<h3>${esc(fold.inizio)} → ${esc(fold.fine)}</h3>`;for(const [key,title,unit] of [['wmae_ctr_pp','Errore CTR',' pp'],['wmae_cpm_eur','Errore CPM',' €']]){const a=fold.annunci.baseline[key],b=fold.annunci.timestral_adjusted[key],max=Math.max(a,b)*1.1;charts+=`<p class="small muted">${title} · più basso è migliore</p>`+[['Baseline',a,false],['Timestral',b,true]].map(([name,v,alt])=>`<div class="barrow"><span>${name}</span><div class="track"><div class="fill ${alt?'alt':''}" style="width:${100*v/max}%"></div></div><span>${num(v,4)}${unit}</span></div>`).join('')}}if(!folds.length){charts=table(['Finestra','MAE CTR (pp)','MAE CPM (€)'],D.validation.folds.map(f=>[esc(f.start+' → '+f.end),num(f.metrics.mae_ctr_pp,4),num(f.metrics.mae_cpm_eur,4)]))}$('validationCharts').innerHTML=charts;
$('remaining').innerHTML=D.manifest.remaining.map(r=>'<li>'+esc(r)+'</li>').join('');$('source').textContent='Metodo corrente: '+D.manifest.forecast_source.method+'. Inferenza: '+(reported?'export precomputati del ramo Timestral, non rieseguiti qui':'baseline calcolata localmente')+'.';$('qa').textContent='Qualità dati: '+D.audit.over_budget_days.length+' giornate con spesa oltre budget segnalate; file originali preservati. '+D.audit.cold_start_rows+' righe future riguardano annunci nuovi.';
$('vertical').addEventListener('change',refreshSets);$('adset').addEventListener('change',render);$('day').addEventListener('change',render);document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));document.querySelectorAll('[role=tabpanel]').forEach(s=>s.hidden=s.id!==b.dataset.tab)}));refreshSets();
</script></body></html>'''
